triggers.trg_membership_order_immutable:
CREATE OR REPLACE FUNCTION trg_membership_order_immutable() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'membership_order is immutable: rows cannot be deleted';
  END IF;
  IF (to_jsonb(NEW) - ARRAY['order_status', 'updated_at']::text[]) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['order_status', 'updated_at']::text[]) THEN
    RAISE EXCEPTION 'membership_order is immutable: only order_status, updated_at may change';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_membership_order_immutable BEFORE UPDATE OR DELETE ON membership_order FOR EACH ROW EXECUTE FUNCTION trg_membership_order_immutable();

triggers.trg_person_consent_grant_immutable:
CREATE OR REPLACE FUNCTION trg_person_consent_grant_immutable() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'person_consent_grant is immutable: rows cannot be deleted';
  END IF;
  IF (to_jsonb(NEW) - ARRAY[]::text[]) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY[]::text[]) THEN
    RAISE EXCEPTION 'person_consent_grant is immutable: only no columns may change';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_person_consent_grant_immutable BEFORE UPDATE OR DELETE ON person_consent_grant FOR EACH ROW EXECUTE FUNCTION trg_person_consent_grant_immutable();
